// Structured care plan details, and the "know before you help" facts.
//
// THE CANONICAL COPY IS backend/src/services/careDetails.ts; the app's copy at
// frontend/src/shared/careDetails.ts is generated by scripts/sync-shared.mjs.
//
// Free text says "needs help with transfers". A carer at 3am needs "full
// hoist, medium sling, green loops, two carers". These are the handful of
// facts per area of care that must be exact, so they are fields, not prose:
// the server validates them, the plan prints them, and the ones marked as
// facts appear on the resident's header and on the record screen, so a carer
// sees them before helping — not after reading fifteen sections.
//
// One source of truth: facts come from the plan's details (plus allergies and
// DNACPR from the resident). An assessment PROPOSES details; a nurse applies
// them. So a fact can never contradict the plan a nurse signed.
//
// Pure; no imports. Tested in backend/tests/caredetails.test.mjs.
// ────────────────────────────────────────────────────────────────────────────

export interface DetailOption { value: string; label: string }
export interface DetailField {
  key: string;
  label: string;
  type: 'text' | 'select' | 'number' | 'bool' | 'list' | 'date';
  options?: DetailOption[];
  unit?: string;
  min?: number;
  max?: number;
  /** If set, a filled-in value becomes a carer-facing fact. */
  fact?: (v: unknown, all: Record<string, unknown>) => string | null;
  /** Red facts are the ones that can kill if missed. */
  tone?: 'red' | 'amber';
  hint?: string;
}

