/** Keep known keys only, coerced to their type. Unknown keys are dropped; '' clears. */
export function cleanDetails(domain: string, raw: unknown, extra: DetailField[] = []): { details: Record<string, unknown>; errors: string[] } {
  // Built-in fields plus any the home has added for this area (v90).
  const fields = [...(DOMAIN_DETAILS[domain] || []), ...extra];
  const src = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw as Record<string, unknown> : {};
  const out: Record<string, unknown> = {};
  const errors: string[] = [];
  for (const f of fields) {
    if (!(f.key in src) || src[f.key] === undefined) continue;
    const v = src[f.key];
    if (v === null || v === undefined || v === '') { out[f.key] = null; continue; }
    if (f.type === 'number') {
      const n = Number(v);
      if (!Number.isFinite(n) || (f.min !== undefined && n < f.min) || (f.max !== undefined && n > f.max)) { errors.push(`${f.label}: give a number${f.min !== undefined ? ` from ${f.min} to ${f.max}` : ''}.`); continue; }
      out[f.key] = n;
    } else if (f.type === 'select') {
      if (!f.options!.some(x => x.value === String(v))) { errors.push(`${f.label}: not one of the options.`); continue; }
      out[f.key] = String(v);
    } else if (f.type === 'bool') {
      out[f.key] = v === true || v === 'true' || v === 'yes';
    } else if (f.type === 'list') {
      const arr = (Array.isArray(v) ? v : String(v).split(/\n|,/)).map(x => String(x).trim()).filter(Boolean).slice(0, 20).map(x => x.slice(0, 200));
      out[f.key] = arr.length ? arr : null;
    } else if (f.type === 'date') {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(String(v))) { errors.push(`${f.label}: give a date.`); continue; }
      out[f.key] = String(v);
    } else {
      out[f.key] = String(v).trim().slice(0, 300);
    }
  }
  return { details: out, errors };
}

/** Merge a change into existing details. null removes a key. */
export function mergeDetails(existing: unknown, change: Record<string, unknown>): Record<string, unknown> {
  const base = existing && typeof existing === 'object' && !Array.isArray(existing) ? { ...(existing as Record<string, unknown>) } : {};
  for (const [k, v] of Object.entries(change)) {
    if (v === null || v === undefined) delete base[k]; else base[k] = v;
  }
  return base;
}

export interface Fact { text: string; tone: 'red' | 'amber' | 'info'; domain: string }

/**
 * The facts a carer must know before helping. Allergies and DNACPR first,
 * then red, then amber, then the rest, in care-plan order.
 */
export function safetyFacts(input: {
  allergies?: string | null;
  dnacpr?: boolean | null;
  sections: { domain: string; applicable?: boolean; details?: unknown }[];
  /** The home's own fields, by care plan area (v90). */
  extraFields?: Record<string, DetailField[]>;
}): Fact[] {
  const out: Fact[] = [];
  const al = (input.allergies || '').trim();
  if (al && !/^(none|nkda|nka|no known( drug)? allerg)/i.test(al)) out.push({ text: `Allergies: ${al}`, tone: 'red', domain: 'allergies' });
  if (input.dnacpr) out.push({ text: 'DNACPR in place', tone: 'red', domain: 'end_of_life' });
  const rest: Fact[] = [];
  for (const s of input.sections) {
    if (s.applicable === false) continue;
    const d = s.details && typeof s.details === 'object' ? s.details as Record<string, unknown> : {};
    for (const f of [...(DOMAIN_DETAILS[s.domain] || []), ...((input.extraFields || {})[s.domain] || [])]) {
      if (!f.fact) continue;
      const v = d[f.key];
      if (v === undefined || v === null || v === '') continue;
      const text = f.fact(v, d);
      if (text) rest.push({ text, tone: f.tone || 'info', domain: s.domain });
    }
  }
  const rank = { red: 0, amber: 1, info: 2 } as const;
  rest.sort((a, b) => rank[a.tone] - rank[b.tone]);
  const seen = new Set(out.map(f => f.text));
  for (const f of rest) if (!seen.has(f.text)) { seen.add(f.text); out.push(f); }
  return out;
}

/** "Every 4 hours" etc. as a readable value for print. */
export function detailValue(f: DetailField, v: unknown): string {
  if (v === null || v === undefined || v === '') return '';
  if (f.type === 'select') return labelOf(f.options || [], v);
  if (f.type === 'bool') return v ? 'Yes' : 'No';
  if (f.type === 'list') return Array.isArray(v) ? v.join(', ') : String(v);
  if (f.type === 'number') return `${v}${f.unit ? ` ${f.unit}` : ''}`;
  return String(v);
}
